const FILE_SUFFIXES = ["logo-on-dark.svg", "logo-on-light.svg", "logo-mono-cream.svg", "logo-mono-ink.svg", "symbol-on-dark.svg", "icon.svg", "overview.png"];

function Chip({ href, label, tone = "dark" }) {
  const tones = {
    dark: "border-white/15 bg-white/5 text-[#F7F1E6] hover:border-[#E85A24] hover:text-[#F2A12C]",
    light: "border-[#150C09]/15 bg-[#150C09]/5 text-[#150C09] hover:border-[#150C09]/40",
    ember: "border-[#F7F1E6]/40 bg-[#F7F1E6]/10 text-[#F7F1E6] hover:bg-[#F7F1E6]/20",
  };
  return (
    <a
      href={href}
      download
      className={`inline-flex min-h-9 items-center gap-1.5 rounded-lg border px-3 text-xs font-semibold transition duration-200 motion-reduce:transition-none ${tones[tone]}`}
    >
      <Download className="h-3.5 w-3.5" aria-hidden="true" />
      <span className="latin">{label}</span>
    </a>
  );
}

/** One refined option, shown whole: the mark, the idea behind it, its grid, its spacing and its symbol. */
export default function LogoStudy({ study = "element", locale = "ar" }) {
  const language = locale === "en" ? "en" : "ar";
  const data = STUDIES[study];
  const text = { ...shared[language], ...data[language] };
  const base = `${data.dir}/${data.file}`;
  const id = (part) => `${study}-${part}-title`;

  const mark = (variant, className, alt = "") => (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={`${base}-logo-${variant}.svg`} alt={alt} width={data.logo.w} height={data.logo.h} className={className} />
  );

  return (
    <div dir={text.direction} lang={language} className="mt-12">
      <figure className="relative flex min-h-64 items-center justify-center rounded-3xl border border-brand/35 bg-[#150C09] px-6 py-16 sm:min-h-96" dir="ltr">
        <OptionNumber no={data.no} className="absolute start-4 top-4" />
        <div className="absolute end-3 top-3 flex gap-1.5">
          <Chip href={`${base}-logo-on-dark.svg`} label="SVG" />
          <Chip href={`${base}-logo-on-dark.png`} label="PNG" />
        </div>
        {mark("on-dark", `h-auto w-full ${data.logo.hero}`, "BRXEL")}
      </figure>

      <div className="mt-4 grid gap-4 sm:grid-cols-2">
        <figure className="relative flex min-h-48 items-center justify-center rounded-2xl bg-[#F7F1E6] px-6 py-12" dir="ltr">
          <div className="absolute end-3 top-3 flex gap-1.5">
            <Chip href={`${base}-logo-on-light.svg`} label="SVG" tone="light" />
            <Chip href={`${base}-logo-on-light.png`} label="PNG" tone="light" />
          </div>
          {mark("on-light", `h-auto w-full ${data.logo.small}`)}
        </figure>
        <figure className="relative flex min-h-48 items-center justify-center rounded-2xl bg-[#E85A24] px-6 py-12" dir="ltr">
          <div className="absolute end-3 top-3">
            <Chip href={`${base}-logo-mono-cream.svg`} label="SVG" tone="ember" />
          </div>
          {mark("mono-cream", `h-auto w-full ${data.logo.small}`)}
        </figure>
      </div>

      <section aria-labelledby={id("idea")} className="mt-10">
        <h3 id={id("idea")} className="text-start text-lg font-semibold text-ice">{text.ideaTitle}</h3>
        <ol className="mt-4 grid gap-3 md:grid-cols-3">
          {text.ideas.map((idea, index) => (
            <li key={idea.title} className="rounded-2xl border border-hairline bg-surface p-5 text-start">
              <span className="latin text-xs font-semibold text-brand-bright">0{index + 1}</span>
              <p className="mt-3 text-base font-semibold text-ice">{idea.title}</p>
              <p className="mt-2 text-sm leading-7 text-ice-muted">{idea.body}</p>
            </li>
          ))}
        </ol>
      </section>

      <section aria-labelledby={id("grid")} className="mt-10">
        <h3 id={id("grid")} className="text-start text-lg font-semibold text-ice">{text.gridTitle}</h3>
        <p className="mt-1 max-w-3xl text-start text-sm leading-7 text-ice-muted">{text.gridNote}</p>
        <figure className="mt-4 overflow-hidden rounded-2xl border border-white/10 bg-[#150C09]" dir="ltr">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={`${base}-construction.svg`} alt={text.gridAlt} width={data.construction.w} height={data.construction.h} loading="lazy" className="h-auto w-full" />
        </figure>
        <dl className="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4">
          {text.specs.map((spec) => (
            <div key={spec.label} className="rounded-xl border border-white/10 bg-[#0C0705]/70 p-4 text-start">
              <dt className="text-xs font-semibold leading-5 text-[#C9BCAC]">{spec.label}</dt>
              <dd className="latin mt-2 text-xl font-bold text-brand-bright" dir="ltr">{spec.value}</dd>
            </div>
          ))}
        </dl>
        <p className="mt-3 max-w-3xl text-start text-xs leading-6 text-ice-muted">{text.unitNote}</p>
      </section>

      <section aria-labelledby={id("spacing")} className="mt-10">
        <h3 id={id("spacing")} className="text-start text-lg font-semibold text-ice">{text.spacingTitle}</h3>
        <p className="mt-1 max-w-3xl text-start text-sm leading-7 text-ice-muted">{text.spacingNote}</p>
        <figure className="mt-4 overflow-hidden rounded-2xl border border-white/10 bg-[#150C09]" dir="ltr">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={`${base}-spacing.svg`} alt={text.spacingAlt} width={data.spacing.w} height={data.spacing.h} loading="lazy" className="h-auto w-full" />
        </figure>
        <div className="mt-4 rounded-xl border border-white/10 bg-[#0C0705]/70 p-4 text-start">
          <p className="text-xs font-semibold text-[#C9BCAC]">{text.gapsLabel}</p>
          <ul className="mt-3 flex flex-wrap gap-2" dir="ltr">
            {data.pairs.map((pair, index) => (
              <li key={pair} className="latin flex items-baseline gap-2 rounded-lg border border-white/10 bg-white/[0.03] px-3 py-2">
                <span className="text-xs text-ice-muted">{pair}</span>
                <span className="text-base font-bold text-brand-bright">{data.gaps[index]}</span>
              </li>
            ))}
          </ul>
        </div>
      </section>

      <section aria-labelledby={id("symbol")} className="mt-10">
        <h3 id={id("symbol")} className="text-start text-lg font-semibold text-ice">{text.symbolTitle}</h3>
        <p className="mt-1 max-w-3xl text-start text-sm leading-7 text-ice-muted">{text.symbolNote}</p>
        <div className="mt-4 grid gap-4 lg:grid-cols-[0.8fr_1.2fr]">
          <figure className="relative flex min-h-56 items-center justify-center rounded-2xl border border-white/10 bg-[#0C0705] p-8" dir="ltr">
            <div className="absolute end-3 top-3">
              <Chip href={`${base}-symbol-on-dark.svg`} label="SVG" />
            </div>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={`${base}-symbol-on-dark.svg`} alt="" width={data.symbol.w} height={data.symbol.h} loading="lazy" className={data.symbol.className} />
          </figure>
          <figure className="relative flex flex-col justify-between gap-6 rounded-2xl bg-[#F7F1E6] p-6 pt-14 sm:p-8 sm:pt-14">
            <div className="absolute end-3 top-3 flex gap-1.5" dir="ltr">
              <Chip href={`${base}-icon.svg`} label="SVG" tone="light" />
              <Chip href={`${base}-icon-512.png`} label="PNG" tone="light" />
            </div>
            <div className="flex flex-wrap items-end gap-5" dir="ltr">
              {[96, 48, 32, 16].map((size) => (
                // eslint-disable-next-line @next/next/no-img-element
                <img key={size} src={`${base}-icon.svg`} alt="" width={size} height={size} loading="lazy" />
              ))}
              <span className="flex items-end gap-2">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={`${base}-icon-ember.svg`} alt="" width={48} height={48} loading="lazy" />
                <span className="text-xs text-[#6B615A]">{text.avatar}</span>
              </span>
            </div>
            <figcaption className="text-sm leading-7 text-[#6B615A]">{text.sizes}</figcaption>
          </figure>
        </div>
      </section>

      <nav aria-label={text.downloads} className="mt-10 rounded-2xl border border-hairline bg-surface p-5 sm:p-6">
        <p className="text-start text-sm font-semibold text-ice">{text.downloads}</p>
        <ul className="mt-4 flex flex-wrap gap-2">
          {FILE_SUFFIXES.map((suffix, index) => (
            <li key={suffix}>
              <a
                href={`${base}-${suffix}`}
                download
                className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-hairline-strong px-4 text-sm font-medium text-ice transition duration-200 hover:border-brand hover:text-brand-bright motion-reduce:transition-none"
              >
                <Download className="h-4 w-4" aria-hidden="true" />
                {text.files[index]}
              </a>
            </li>
          ))}
        </ul>
        <p className="mt-4 text-start text-xs leading-6 text-ice-muted">{text.status}</p>
      </nav>
    </div>
  );
}
